head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnDisplayFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 displayFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 displayFormat 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "displayFormat(필수) 파라미터로 dataType='text' 인 Column 은 '#' 마스크 문자를 사용하여 형식을 설정합니다.",
        "displayFormat(필수) 파라미터로 dataType='date' 인 Column 은 'y','M','d','E' 마스크 문자를 사용하여 형식을 설정합니다.",
        "displayFormat(필수) 파라미터로 dataType='time' 인 Column 은 'H','m','s' 마스크 문자를 사용하여 형식을 설정합니다.",
        "displayFormat(필수) 파라미터로 그외 dataType 인 Column 은 '#','0',',','.' 마스크 문자를 사용하여 형식을 설정합니다.",
        "Column 의 displayFormatter 속성이 설정된 경우 displayFormat 속성은 무시됩니다.",
        "Column 의 customFormatter 속성이 설정된 경우 최종 데이터 표시는 customFormatter 로 처리되므로 displayFormat 결과가 덮어 써질 수 있습니다.",
        "inputType='calendar' 이고 userEditFormat=true 인 Column 에서 setColumnDisplayFormat() 메소드로 displayFormat 속성 설정 시 editFormat 속성도 함께 설정됩니다.",
    ]
}



// displayFormatter Column(인덱스 5) 용 사용자 함수 : 값과 무관하게 '[' + 값 + ']' 로 표시 -> displayFormat 무시 확인용
scwin.fmtBracket = function (value) {
    return "[" + value + "]";
};

// customFormatter Column(인덱스 6) 용 사용자 함수 : displayFormat 적용 결과 위에 다시 덮어쓰는지 확인용
scwin.fmtCustom = function (value) {
    return "C:" + value;
};

// columnInfo(컬럼 인덱스) 별로 해당 Column 의 dataType 에 맞는 displayFormat 마스크 매핑
//  text="#" / date="y,M,d,E" / time="H,m,s" / 그외(number)="#,0,,,." / calendar 는 date 형식
scwin.colFormatMap = {
    "0": "###-####",    // ctext (text)
    "1": "###-####",    // chide (text, 숨김)
    "2": "#,##0.00",    // cnum (number)
    "3": "yyyy-MM-dd",  // cdate (date)
    "4": "HH:mm:ss",    // ctime (time)
    "5": "#,##0.00",    // cfmtter (number, displayFormatter -> 무시)
    "6": "#,##0.00",    // ccustom (number, customFormatter -> 덮어씀)
    "7": "yyyy.MM.dd"   // ccal (calendar/date)
};

// columnInfo 셀렉트박스 선택이 바뀌면 해당 컬럼에 매핑되는 displayFormat 값을 par_displayFormat 셀렉트박스에 자동 선택
scwin.par_columnInfo_onchange = function () {
    let col = par_columnInfo.getValue();
    let fmt = scwin.colFormatMap[col];
    if (typeof fmt !== 'undefined') {
        par_displayFormat.setValue(fmt);
    }
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 columnInfo 선택값(0)에 맞는 displayFormat 자동 선택
    par_columnInfo.setValue("0");
    scwin.par_columnInfo_onchange();
};



// comp 생성 : dataType 별 Column(text/number/date/time) + displayFormatter/customFormatter/calendar Column 구성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스(숨김 포함) - 0:ctext(text) / 1:chide(text, setColumnVisible(1,false) 로 숨김) / 2:cnum(number) / 3:cdate(date) / 4:ctime(time) / 5:cfmtter(displayFormatter=fmtBracket 설정) / 6:ccustom(customFormatter=fmtCustom 설정) / 7:ccal(inputType=calendar, userEditFormat=true). 데이터 Row 3개.\n[절차] columnInfo(인덱스) 와 displayFormat 선택/입력 후 (setColumnDisplayFormat 실행) -> 해당 Column 셀의 화면 표시값이 형식대로 바뀌는지 확인.\n[확인] text(0)=마스크# / number(2)=#,0,. / date(3)=yMdE / time(4)=Hms 형식 적용. displayFormatter Column(5) 은 무시(fmtBracket 결과 유지). customFormatter Column(6) 은 덮어씀(fmtCustom 결과). calendar Column(7) 은 editFormat 동반 설정(getColumnEditFormat 으로 확인)."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (dataType 별 컬럼)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="ctext" name="ctext" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chide" name="chide" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cnum" name="cnum" dataType="number"></w2:column>';
    strDlt += '<w2:column id="cdate" name="cdate" dataType="date"></w2:column>';
    strDlt += '<w2:column id="ctime" name="ctime" dataType="time"></w2:column>';
    strDlt += '<w2:column id="cfmtter" name="cfmtter" dataType="number"></w2:column>';
    strDlt += '<w2:column id="ccustom" name="ccustom" dataType="number"></w2:column>';
    strDlt += '<w2:column id="ccal" name="ccal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "ctext": "1234567", "chide": "숨김1", "cnum": "1250",  "cdate": "20250115", "ctime": "143025", "cfmtter": "1000", "ccustom": "2000", "ccal": "20250115" },
        { "ctext": "9876543", "chide": "숨김2", "cnum": "30500", "cdate": "20251231", "ctime": "090500", "cfmtter": "2000", "ccustom": "3000", "ccal": "20251231" },
        { "ctext": "5550000", "chide": "숨김3", "cnum": "780",   "cdate": "20250707", "ctime": "235959", "cfmtter": "3000", "ccustom": "4000", "ccal": "20250707" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (dataType 별 Column + displayFormatter/customFormatter/calendar Column)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnDisplayFormat 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="110" inputType="text" id="h0" value="0:text"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="h1" value="1:숨김"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h2" value="2:number"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h3" value="3:date"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h4" value="4:time"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h5" value="5:displayFmtter"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h6" value="6:customFmtter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h7" value="7:calendar"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // 0 : text -> setColumnDisplayFormat(0,"###-####") 등 # 마스크
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="ctext" dataList="ctext"></w2:column>';
    // 1 : text 숨김(setColumnVisible(1,false)) -> 숨김 Column 포함 인덱스 검증용
    strTarget += '<w2:column width="80" inputType="text" dataType="text" id="chide" dataList="chide"></w2:column>';
    // 2 : number -> setColumnDisplayFormat(2,"#,##0.00") (그외 dataType, #/0/,/. 마스크)
    strTarget += '<w2:column width="110" inputType="text" dataType="number" id="cnum" dataList="cnum"></w2:column>';
    // 3 : date (초기 displayFormat=yyyy/MM/dd) -> setColumnDisplayFormat(3,"yyyy-MM-dd") 시 표시 변화 (y/M/d/E 마스크)
    strTarget += '<w2:column width="110" inputType="text" dataType="date" displayFormat="yyyy/MM/dd" id="cdate" dataList="cdate"></w2:column>';
    // 4 : time -> setColumnDisplayFormat(4,"HH:mm:ss") (H/m/s 마스크)
    strTarget += '<w2:column width="100" inputType="text" dataType="time" id="ctime" dataList="ctime"></w2:column>';
    // 5 : displayFormatter 설정 Column -> setColumnDisplayFormat 호출해도 무시(fmtBracket 결과 유지)
    strTarget += '<w2:column width="110" inputType="text" dataType="number" id="cfmtter" dataList="cfmtter" displayFormatter="scwin.fmtBracket"></w2:column>';
    // 6 : customFormatter 설정 Column -> setColumnDisplayFormat 결과가 customFormatter 로 덮임(fmtCustom 결과)
    strTarget += '<w2:column width="110" inputType="text" dataType="number" id="ccustom" dataList="ccustom" customFormatter="scwin.fmtCustom"></w2:column>';
    // 7 : calendar + useEditFormat -> setColumnDisplayFormat(7,...) 시 editFormat 도 함께 설정
    //  (주의) 컬럼 속성명은 useEditFormat (가이드 @spec 의 userEditFormat 은 오기, 엔진은 useEditFormat 사용)
    strTarget += '<w2:column width="*" inputType="calendar" dataType="date" useEditFormat="true" id="ccal" dataList="ccal"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(chide, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);
}



// [실행] setColumnDisplayFormat : columnInfo(인덱스) 와 displayFormat 으로 해당 Column 의 displayFormat 속성을 설정한다.
//  - 설정 후 해당 Column 의 모든 Row 화면 표시값(td.textContent) 을 수집하여 형식이 적용되었는지 확인
//  - calendar(useEditFormat=true) Column(7) 은 editFormat 동반 설정 여부도 함께 확인
scwin.btn_setColumnDisplayFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let displayFormat = par_displayFormat.getValue();
    let colID = target1.getColumnID(columnInfo);
    let cnt = dlt_bind.getRowCount();

    // setColumnDisplayFormat 호출
    target1.setColumnDisplayFormat(columnInfo, displayFormat);

    // 적용된 해당 Column 의 모든 Row 화면 표시값 수집
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnInfo + "']");
        arr.push(td ? td.textContent.trim() : '');
    }

    let msg = "setColumnDisplayFormat(" + columnInfo + ", '" + displayFormat + "') [" + colID + "] -> 화면 표시값 : " + arr.join(', ');

    // calendar + useEditFormat Column 은 editFormat 동반 설정 확인
    //  (calendar 의 editFormat 은 calendar 입력 객체에 적용되므로 해당 입력의 editFormat 으로 확인)
    if (colID === "ccal") {
        let editFmt = scwin.getCalendarEditFormat(columnInfo);
        msg += "\n[editFormat 동반 설정] displayFormat 의 마스크 문자가 editFormat 으로 함께 설정됨 : " + editFmt;
    }

    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// calendar Column 의 editFormat 조회 : displayFormat 설정 시 letters 가 '#' 로 치환되어 calendar 입력의 editFormat 으로 설정됨
scwin.getCalendarEditFormat = function (columnInfo) {
    try {
        let cellInfo = target1.getCellInfo(columnInfo);
        let input = target1.getInput(cellInfo);
        if (input && input._editFormat) {
            return Array.isArray(input._editFormat) ? input._editFormat.join("||") : input._editFormat;
        }
        return "(미설정)";
    } catch (e) {
        return "(조회불가)";
    }
}
